"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/icon-button.css";
import type { ReactNode } from "react";
import { Button, type ButtonProps } from "./button";
import { Tooltip, TooltipContent, TooltipTrigger } from "./tooltip";
import { cn } from "../../lib/cn";

export type IconButtonProps = Omit<ButtonProps, "children" | "leadingIcon" | "trailingIcon"> & {
  children?: ReactNode;
  "aria-label": string;
  tooltip?: string;
};

export function IconButton({ children, className, tooltip, ...props }: IconButtonProps) {
  const button = (
    <Button
      className={cn("whatiuse-icon-button", className)}
      focusableWhenDisabled={Boolean(tooltip) && props.disabled}
      {...props}
    >
      {children}
    </Button>
  );

  if (!tooltip) return button;

  return (
    <Tooltip>
      <TooltipTrigger render={button} />
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-icon-button { width: var(--whatiuse-control-height-md); padding: 0; }

.whatiuse-icon-button.whatiuse-button--small { width: var(--whatiuse-control-height-sm); padding: 0; }

.whatiuse-icon-button.whatiuse-button--large { width: var(--whatiuse-control-height-lg); padding: 0; }

.whatiuse-icon-button .whatiuse-button__content { display: grid; width: 100%; height: 100%; place-items: center; }

.whatiuse-icon-button .whatiuse-button__content > span:last-child { display: grid; width: 100%; height: 100%; place-items: center; line-height: 0; }

.whatiuse-icon-button svg { width: calc(var(--whatiuse-icon-size) + 1px); height: calc(var(--whatiuse-icon-size) + 1px); transform: none; }
}
